import assert from'node:assert/strict';import{writeFile}from'node:fs/promises';import{fileURLToPath}from'node:url';const{chromium}=await import(process.env.MX_PLAYWRIGHT_MODULE||'playwright-core');const out=fileURLToPath(new URL('../../docs/qa/layout-audit-2026-11-16',import.meta.url));const b=await chromium.launch({executablePath:'/Applications/Google Chrome.app/Contents/MacOS/Google Chrome',headless:true,args:['--mute-audio']});const results=[];
try{const p=await b.newPage({viewport:{width:1100,height:1300},isMobile:true,hasTouch:true});let errors=[];p.on('pageerror',e=>errors.push(e.message));const load=async(layout,scene)=>{errors=[];await p.goto('http://127.0.0.1:4179/tests/fixtures/layout-audit.html?'+new URLSearchParams({layout,scene,hero:3}));await p.locator('#audit-stage[data-ready=true]').waitFor();};const passed=(layout,test)=>{assert.equal(errors.length,0,errors.join('\n'));results.push({layout,test,result:'pass'});console.log(layout,test);};
for(const layout of['original','balanced','oval','classic']){
 await load(layout,'insurance-multi');await p.locator('.mx-insurance').waitFor();await p.locator('.mx-insurance-options button').first().click();await p.locator('.mx-insurance-tabs button').nth(1).click();await p.locator('.mx-insurance-options button').nth(1).click();await p.locator('.mx-insurance-tabs button').first().click();await p.locator('.mx-insurance-buy').click();await p.locator('.mx-insurance').waitFor({state:'hidden'});passed(layout,'multi-pot selection and purchase');
 await load(layout,'second-board');await p.locator('.mx-second-agree').click();await p.locator('.mx-second-pcs').waitFor({state:'hidden'});await p.waitForFunction(()=>[...document.querySelectorAll('.mx-board')].filter(e=>e.checkVisibility()).length>=2);passed(layout,'second-board agree');
 await load(layout,'history');await p.locator('.mx-history-details').waitFor();await p.locator('.mx-history-details').click();assert.ok((await p.locator('#audit-stage').innerText()).includes('离线验收牌谱'));passed(layout,'history details populated');
 await load(layout,'bring-score');for(let i=0;i<4&&await p.locator('.mx-buyin-confirm').isVisible();i++)await p.locator('.mx-buyin-confirm').click();await p.locator('.mx-buyin-overlay').waitFor({state:'hidden'});assert.equal(await p.locator('.mx-seat-mine').getAttribute('data-seat'),'3');passed(layout,'security and local buy-in');
 await load(layout,'dealer-self');await p.getByText('逐元素模拟编辑器（修改当前指定座位；仅本地数据）',{exact:true}).click();await p.locator('[data-audit-field=seat]').fill('2');await p.getByRole('button',{name:'读取座位',exact:true}).click();await p.locator('[data-audit-field=name]').fill('编辑器验收');await p.locator('[data-audit-field=chips]').fill('12345678');await p.getByRole('button',{name:'应用玩家元素',exact:true}).click();assert.equal(await p.locator('.mx-seat[data-seat="2"] .mx-player-name').innerText(),'编辑器验收');await p.getByRole('button',{name:'设为庄家',exact:true}).click();assert.equal(await p.locator('.mx-seat[data-seat="2"] .mx-dealer').isVisible(),true);passed(layout,'per-player editor and dealer change');
}
}finally{await b.close();await writeFile(out+'/workbench-verification.json',JSON.stringify(results,null,2));}console.log(results.length);
